def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def objsha(x):return hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def gid(pre):return next(g for g in G if g.startswith(pre))
def witness(g):
 assert objsha(G[g])==L[g]['wholeGoalBodySHA256'] and objsha(P[g]['profile'])==L[g]['wholeProfileBodySHA256']
 return {'goalId':g,'wholeGoalBodySHA256':objsha(G[g]),'wholeProfileBodySHA256':objsha(P[g]['profile']),'PRecordLineSHA256':L[g]['PRecordLineSHA256'],'goalFingerprint':P[g]['goalFingerprint'],'profileFingerprint':P[g]['profileFingerprint'],'requiredExpectationIds':P[g]['profile']['coverageExpectations']['requiredExpectationIds'],'caseIds':[c['id'] for c in P[g]['profile']['applicationCaseBriefs']],'ownExactPriorReadingPin':{'path':str(LP),'sha256':sha(LP)}}
NOTES={
73:('HOLD','REVISE','747c5777 fordert ΔEN für H–Cl/C–O/O–H und erklärt deren Bindungsdipole; 448815cc erklärt die bereits vorgegebenen Cu-/NaCl-/Cl2-Modelle. Die geforderte Ermittlung der Bindungstypen unter Anwendung von EN ist nicht dieselbe Leistung wie diese beiden getrennten Aufgaben. Ein unpolares CO2-Molekül mit polaren C–O-Bindungen liefert insbesondere keinen unpolaren Bindungsfall. Mein FIRST hatte die Methoden-/Klassifikationsverknüpfung zu weit als Union angerechnet. Es fehlt keine starre EN-Grenzzahl und keine zusätzliche Labormethode.'),
82:('HOLD','RETAIN','Die vollständigen Alkanolfälle verlangen Butan-1-/2-ol-Benennung, eine verzweigte Benennung sowie C4/C5-Konstitutionsisomere. dd58c029 erklärt CH2-Homologie ausdrücklich für Kohlenwasserstoffe. Die zusätzliche Beschreibung der homologen Alkoholreihe ist in 536b48b2/e9b61d96 nicht verlangt; vorhandene C4- und C5-Alkohole allein prüfen diesen Zusammenhang nicht. Keine Zahl von Reihengliedern oder Zusatzaufgaben wird gefordert.'),
92:('HOLD','REVISE','0503c975 erklärt zusätzlichen fossilen CO2-Bestand, a0e8f0f2/8b98d8ba recherchierte Rohstoff-/Ressourcenfolgen und Nachhaltigkeitsmaßnahmen. Es fehlt der verbindliche Schritt vom fossilen Treib-/Heizstoffeinsatz zu einer beschriebenen und bewerteten Klimawirkung. Eine CO2-Bilanz oder das allgemeine Kriterium Klima ersetzt diesen Zusammenhang nicht. Verlangt wird weder eine eigene Klimamessung noch ein vollständiges Strahlungsmodell; mein FIRST hatte aus dem allgemein möglichen Recherchethema zu viel aktuelle Pflichtdeckung abgeleitet.'),
98:('HOLD','REVISE','Die Kunststoff-Werbekritik von 8b98d8ba enthält reale Zusatzrecherche und Argumentprüfung. 38e30bb9 verlangt echte Präsentation der eigenen Lösemittel-Prozessauswertung oder Liganden-Modellprüfung. Keiner der ganzen aktuellen Fälle fordert, gerade die recherchierten kontroversen Kunststoff-Medienargumente zusammenzufassen und zu präsentieren. Meine frühere Bedingung nur entsprechend instanziiert war noch keine aktuelle verpflichtende Instanziierung. Es fehlt diese Gegenstandsverknüpfung, keine weitere Präsentations- oder Quellenzahl.'),
135:('HOLD','REVISE','0bf26276 behandelt Alltags-pH; ac8b6c0f recherchiert tatsächlich analog und digital am pharmazeutischen Säurelöslichkeitsmodell. Die vollen Präsentationsfälle von 38e30bb9 behandeln Lösemittelrückgewinnung und Ligandenbelegung, keine recherchierte Alltagsrelevanz von Säuren/Basen. Die gemeinsame Themen-/Recherche-/Präsentationsleistung ist nicht verbindlich gebunden. Eine solche Aufgabe könnte den bestehenden Methoden entsprechen, ist aber im aktuellen Vertrag nicht bereits gefordert.'),
136:('HOLD','REVISE','882630ba erklärt im tatsächlichen anthropogenen Carbonatfall den zusätzlichen fossilen Eintrag, CO2-Lösung/Protolyse und begrenzte Quellenurteile; 5a58126e ergänzt offene Gleichgewichte. Der Fall nennt ökologische Bewertungsgrenzen und dass Emissionsminderung/Anpassung Belege benötigen, fordert aber keine aus einer ökologischen Bewertung der Ozeanversauerung abgeleiteten Handlungsoptionen. Allgemeine Ressourcenmaßnahmen aus 8b98d8ba schließen diesen konkreten Ableitungsschritt nicht. Kein bestimmter Organismus, Zahlen-pH, reales Meerwasserexperiment oder Optionspensum wird hinzugefügt.'),
138:('HOLD','REVISE','Der ganze 3ce81f96-Vertrag nennt Konzentration, Zerteilung, Temperatur und Stoffart; der Druckeinfluss gehört gerade nicht zu seinen vier Faktoren. 536030f8/56115f9d liefern kontrollierte Oberfläche-/Temperatur-/Zeit-Vergleiche und 13838147 Konzentrationsgesetze, keine verbindliche qualitative/quantitative Druck-Rate-Deutung. Im FIRST war diese benannte Quellenbedingung zu pauschal angerechnet. Es fehlt ein Druckbezug, nicht ein universelles Ratengesetz oder eine feste Versuchszahl für jeden Faktor.'),
142:('HOLD','REVISE_QUALIFIED','Der eigene digitale 9e3fae29-Kinetikfall bleibt echter Dateinachweis: gegebene synthetische c(t)-Punkte werden in einer eigenen Datei ausgewertet, verändert, linearisiert und über Residuen geprüft. Er verlangt damit tatsächliches Darstellen/Auswerten, jedoch keine als solche erkennbare digitale Aufnahme eines Konzentrations-Zeit-Verlaufs. Das erneute Speichern der gelieferten Idealdaten habe ich im FIRST zu weit dem Aufnehmen gleichgesetzt. 56115f9d nimmt reale Temperatur-/Gasvolumenwerte auf, bindet dies aber nicht an eine digitale c(t)-Aufnahme. Der HOLD betrifft nur diesen Operatorzusammenhang; daraus folgt ausdrücklich keine zusätzliche Pflicht zu einem eigenen physischen Versuch, einem bestimmten Sensor, Automation oder synchronem Logging. Eine tatsächlich verpflichtende digitale Aufnahme mit wahrheitsgemäßem Mess-/Simulations-/Datenursprung müsste konkret nachgewiesen sein.'),
165:('ACCEPT','RETAIN_QUALIFIED','197bc2c5 fordert im ganzen aktuellen Ziel ausdrücklich das Verknüpfungsprinzip der Primärstruktur und lässt im konkreten case-a die gerichtete Folge Gly–Ala selbst als Strukturformel mit freiem Amino-/Carboxyterminus erzeugen. Das ist ein positiver geordneter Aminosäurefolgen-Witness, nicht bloß das Wort keine Primärhydrolyse in 065d764c. 065d764c ergänzt räumliche Helix-/Tertiär-/Quartärkontakte und deren geänderte Folgen. Die Union trägt somit die vier Ebenen. Eine längere vollständige Proteinsequenz oder weitere Darstellungstechnik wäre eine ungedruckte Zusatzforderung. Der positive Primärbeitrag muss in der Bindung ausdrücklich auf 197bc2c5/case-a stehen.'),
200:('HOLD','REVISE','Bioethanol ist über Stärkehydrolyse/Gärung und Biodiesel über Umesterung konkret erklärt. Das in dieser Union ebenfalls unterschiedene Pflanzenöl wird in 0959eef2 als vorhandenes Triglyceridgemisch/Herkunft/Nutzung bewertet; seine Gewinnung/Herstellung wird nicht erläutert. Der eigene FIRST hatte diesen dritten Beitrag zu großzügig als Herstellungsweg gezählt. Es fehlt keine BTL-Pflicht im gemeinsamen GK/LK-Abschnitt und keine starre Zahl zusätzlicher Verfahren; dieser tatsächlich benannte Pflanzenölweg bleibt unvollständig.'),
202:('ACCEPT','REVISE','Der aktuelle 9f892457-Vertrag enthält required expectation own-action-and-fresh-change ausdrücklich: Die Person reflektiert eigene mögliche Informations-, Nutzungs- und Meldehandlungen. Der ganze Kühlmittelkontext verknüpft eigene Nutzung/Bedarf, Schadensmeldung und fachgerechten Service mit Ozon-/Klimafolgen und globalen Ressourcen-/Nachhaltigkeitsfragen; der Ammoniakkontext ergänzt Ressourcenreflexion. Damit ist der eigene Bezug tatsächlich verpflichtend. Mein FIRST hatte diese eigene Handlungserwartung übersehen. Kein privates Konsumtagebuch, persönliche CO2-Rechnung oder gefährliches Eingreifen wird zusätzlich gefordert.'),
205:('HOLD','REVISE','a0e8f0f2/8b98d8ba verlangen tatsächliche Rohstoff-/Mobilitätsrecherche und Quellen-/Werbekritik. ac8b6c0f erzwingt analoge und digitale Fundstellen, jedoch in den konkreten Säurelöslichkeits-/Lösemittelrückgewinnungsfällen. Ein verpflichtender kritischer analoger UND digitaler Informationsvergleich zu nachwachsenden Rohstoffen und Klimawandel ist damit nicht konkret nachgewiesen. Meine FIRST-Formulierung nur thematisch instanziiert beschrieb eine mögliche zusätzliche Verknüpfung; sie war kein vorhandener Pflichtzeuge. Kein zusätzliches Experiment oder Methodenpensum wird verlangt.')
}

