 assert sha(INPUT)=='7798aad012ad3c50567f3a573fb03cfa3e653616edbe0a8f85c20a963b437001'
 selector=INPUT.parent/'SELECTOR.informed-dissent-input.sealed.json'
 assert sha(selector)=='d814a36ea8dc6f90aeda3d34cd7567f17cc9720ec66ee037fde1bed1d2a292cf'
 for p in J['frozenFirstPins']+list(J['centralPins'].values())+[J['sourceInventoryPin']]:assert sha(p['path'])==p['sha256']
