  rows.append({'ordinal':n,'sourceGoalId':r['sourceGoal']['id'],'sourceGoalBodySHA256':objsha(r['sourceGoal']),'sourceClauseIds':r['sourceGoal']['sourceClauseIds'],'sourceDuty':r['sourceGoal']['description'],'sourceCourseLevel':r['sourceGoal']['courseLevel'],'sourceScope':r['firstIndependentA']['sourceScope'],'firstA':r['firstIndependentA']['decision'],'firstB':r['firstIndependentB']['decision'],'informedDecision':dec,'ownFirstRelation':change,'rationaleDe':note,'currentCarrierWitnesses':[witness(g) for g in ids],'originalFIRSTsOverwritten':False})
